(309, 1, '2024-04-28 18:01:55', '2024-04-28 18:01:55', '.mg-latest-news .bn_title .title {\n    background-color: #2E5F96;\n    color: #fff;\n}\n\n.bs-default .bs-menu-full {\n    background: #2E5F96;\n}\n\na{\n	color:#2e5f96;\n}\n\n.bs-widget-title .title {\n    background: #2e5f96;\n    color: #fff;\n}\n\n.bs_upscr {\n    background: #2e5f96;\n    border-color: #2e5f96;\n    color: #fff !important;\n}\n\n.bs-widget-title {\n    border-color: #2e5f96;\n}\n\n.navigation.pagination .nav-links .page-numbers.current, .navigation.pagination .nav-links a:hover, a.error-btn, .post-page-numbers.current {\n    background-color: #2e5f96;\n    color: #fff;\n}\n\nblockquote::before {\n    color: #2e5f96;\n}\n\nblockquote {\n    background: var(--bor-color);\n    border-left: 5px solid #2e5f96;\n}\n\n.widget_block h2, footer .wp-block-heading {\n    background: #2e5f96;\n    color: #fff;\n}\n\n.widget_block h2:before, footer .wp-block-heading::before {\n    background: #2e5f96;\n}\n\ninput[type=\"submit\"], button {\n    background: #2e5f96;\n    border-color: #2e5f96;\n    color: #fff;\n}\n', 'newsair', '', 'publish', 'closed', 'closed', '', 'newsair', '', '', '2024-04-29 16:00:46', '2024-04-29 16:00:46', '', 0, 'http://localhost/wordpress/2024/04/28/newsair/', 0, 'custom_css', '', 0),
